GEN.race = function (lv) {
  const pool = lv === 1 ? ['numbers', 'letters', 'count'] : ['numbers', 'letters', 'count', 'add', 'first'];
  const q = GEN[pick(pool)](lv), ans = q.opts.find((o) => o.val === q.ans);
  const others = shuffle(q.opts.filter((o) => o !== ans)).slice(0, 2);
  q.opts = shuffle([ans, ...others]);
  return q;
};

